'use strict';const assert=require('node:assert/strict'),fs=require('node:fs'),strategy=require('../../backend/tools/strategic_budget_v442/strategy.js'),api=require('../../backend/tools/strategic_budget_v442/budget-model.js');
const fixture=()=>{const names=[['Financiamento Imobiliário',2000],['Compromissos Financeiros',500],['Empréstimos',700],['Mercado',1000],['Saúde',800],['Restaurantes',1000],['Vestuário',200],['IPVA',0]],months=Array.from({length:12},(_,i)=>({month:'2027-'+String(i+1).padStart(2,'0'),target:6200,actual:0,pending:0,income_target:3000,income_regular:0,income_extraordinary:0,income_bonus:0,income_thirteenth:0,started:false,complete:false}));return{ok:true,version:'budget-v441',year:2027,as_of:'2026-11-12',plan_revision:0,proposed:true,reference:{from:'2026-05-01',to:'2026-10-31',months:6,expected_months:6,salary_months:3,salary_monthly:3000},income_approvals:{year:false,months:{}},category_aliases:{},months,rows:names.map(([category,reference_monthly])=>({category,reference_monthly,months:months.map(m=>({month:m.month,target:reference_monthly,actual:0,pending:0,target_basis:'history'}))})),basis:'canonical_consumption_not_card_payment',flow_provision_included:false,unclassified_actual:0};};
const flow={flow:{current_future:{from:'2026-11-12',to:'2027-12-31',events:[{event_date:'2027-01-15',description:'Adiantamento Quinzenal',signed_amount:2000,source:'legacy_fix86'},{event_date:'2027-01-30',description:'Salário líquido',signed_amount:1000,source:'legacy_fix86'},{event_date:'2027-01-19',description:'Complemento do 13º',signed_amount:6789.12,source:'legacy_fix86',category:'13º salário'},{event_date:'2027-01-20',description:'Bônus',signed_amount:10000,source:'current_event'},{event_date:'2027-01-20',description:'Parcela financiamento',category:'Financiamento Imobiliário',signed_amount:-2500,source:'current_event',source_ref:'mortgage',confidence:'user_flow_editable'},{event_date:'2027-01-30',description:'Coopharma',category:'Compromissos Financeiros',signed_amount:-500,source:'economic_withholding'},{event_date:'2027-01-03',description:'Fatura Aeternum',category:'Cartões',signed_amount:-15000,source:'card_invoice'},{event_date:'2027-01-03',description:'Novos gastos',category:'Vestuário',signed_amount:-15000,source:'card_budget_v412'},{event_date:'2027-01-25',description:'IPVA',category:'IPVA',signed_amount:-1000,source:'current_event',source_ref:'tax',confidence:'user_flow_editable'}]}}};
const card={family:'aeternum',cycles:[{month:'2027-01-01',amount:15000,items:[{source_id:'purchase1',reference_month:'2027-01-01',category:'Vestuário',description:'Parcela recebida',amount:100,total_installments:6,installment_number:3}]}]},cards={complete:true,cards:[card,structuredClone(card)]};
const results=[];function test(n,f){f();results.push(n);console.log('PASS',n);}const raw=fixture(),before=JSON.stringify(raw),p=strategy.derive(raw,flow,cards),m=api.build(p),v=api.view(m,'month','2027-01');
test('Planning never mutates actuals or source inputs',()=>{assert.equal(JSON.stringify(raw),before);assert.equal(v.actual,0);assert.equal(p.flow_provision_included,false);});
test('Monthly net pay excludes bonus and the thirteenth complement',()=>{assert.equal(v.incomeTarget,300000);assert.equal(v.extra,0);assert.equal(v.thirteenth,0);});
test('Known contractual payment is preserved above its historical reference',()=>{assert.equal(p.rows.find(r=>r.category==='Financiamento Imobiliário').months[0].target,2500);});
test('Ended Itaú payments and payroll-deducted Coopharma are not added again',()=>{for(const c of['Empréstimos','Compromissos Financeiros'])assert.equal(p.rows.find(r=>r.category===c).months[0].target,0);});
test('An invoice, the Flow provision and duplicated additional-card items are not new expenses',()=>{assert.equal(p.rows.find(r=>r.category==='Vestuário').months[0].target,100);assert.equal(p.rows.find(r=>r.category==='Vestuário').months[0].strategy.details.length,1);});
test('A real deficit remains visible after suspending new discretionary spending',()=>{assert(v.plannedBalance<0);assert.equal(p.rows.find(r=>r.category==='Restaurantes').months[0].target,0);assert.equal(p.rows.find(r=>r.category==='Saúde').months[0].target,800);});
test('Seasonal commitments stay in their documented month',()=>{assert.equal(p.rows.find(r=>r.category==='IPVA').months[0].target,1000);assert.equal(p.rows.find(r=>r.category==='IPVA').months[1].target,0);});
test('Current-month recorded spending is added to distinct remaining payments without repeating recorded card purchases',()=>{const q=fixture();q.as_of='2027-01-12';const mortgage=q.rows.find(r=>r.category==='Financiamento Imobiliário').months[0],clothes=q.rows.find(r=>r.category==='Vestuário').months[0];mortgage.actual=200;mortgage.card_actual=0;clothes.actual=100;clothes.card_actual=100;q.months[0].actual=300;const z=strategy.derive(q,flow,cards);assert.equal(z.rows.find(r=>r.category==='Financiamento Imobiliário').months[0].strategy.floor,2700);assert.equal(z.rows.find(r=>r.category==='Vestuário').months[0].strategy.floor,100);});
test('Owner-approved category and income goals survive a new proposal',()=>{const q=fixture();q.rows.find(r=>r.category==='Mercado').months[0]={...q.rows.find(r=>r.category==='Mercado').months[0],target:777,target_basis:'owner'};q.months[0].income_target=2800;q.income_approvals.months['2027-01']=true;const z=strategy.derive(q,flow,cards);assert.equal(z.rows.find(r=>r.category==='Mercado').months[0].target,777);assert.equal(z.months[0].income_target,2800);});
test('No retrospective historical mean is invented as an approved budget',()=>{const q=fixture();q.year=2026;q.months.forEach(x=>x.month=x.month.replace('2027','2026'));q.rows.forEach(r=>r.months.forEach(x=>x.month=x.month.replace('2027','2026')));const z=strategy.derive(q,flow,cards);assert.equal(z.months[0].target,null);assert.equal(z.rows[0].months[0].target_basis,'proposal');assert.equal(z.strategy.pastWithoutPlan,10);});
test('Incomplete commitments or unknown approval state never produce a confident plan',()=>{assert.throws(()=>strategy.derive(fixture(),flow,{...cards,complete:false}));const q=fixture();delete q.income_approvals;assert.throws(()=>strategy.derive(q,flow,cards));});
test('A surplus does not inflate discretionary proposals past their declared income and history limits',()=>{const q=fixture(),f=structuredClone(flow);f.flow.current_future.events=f.flow.current_future.events.filter(e=>e.signed_amount>0);const z=strategy.derive(q,f,{complete:true,cards:[]});const restaurants=z.rows.find(r=>r.category==='Restaurantes').months[0],clothes=z.rows.find(r=>r.category==='Vestuário').months[0];assert.equal(restaurants.target,150);assert.equal(clothes.target,100);assert.equal(z.months[0].target,2050);assert.equal(z.strategy.months[0].balance,950);});
test('Registered category aliases align installments with actuals and preserve approved goals',()=>{const q=fixture(),c=structuredClone(cards);q.as_of='2027-01-12';q.category_aliases={'Pessoa — Roupa':'Vestuário'};const r=q.rows.find(r=>r.category==='Vestuário').months[0];r.actual=100;r.card_actual=100;r.target=250;r.target_basis='owner';c.cards.forEach(x=>x.cycles[0].items[0].category='Pessoa — Roupa');const z=strategy.derive(q,flow,c);assert(!z.rows.some(r=>r.category==='Pessoa — Roupa'));assert.equal(z.rows.find(r=>r.category==='Vestuário').months[0].strategy.floor,100);assert.equal(z.rows.find(r=>r.category==='Vestuário').months[0].target,250);});
test('The mortgage spelling used by the calendar shares the established planning category',()=>{const f=structuredClone(flow);f.flow.current_future.events.find(e=>e.source_ref==='mortgage').category='Financiamento imóvel';const z=strategy.derive(fixture(),f,cards);assert.equal(z.rows.find(r=>r.category==='Financiamento Imobiliário').months[0].target,2500);assert(!z.rows.some(r=>r.category==='Financiamento imóvel'));});
test('A new essential category retains known installments and explicitly requires a needs review',()=>{const c=structuredClone(cards);c.cards.forEach(x=>x.cycles[0].items[0].category='Necessidade saúde nova');const z=strategy.derive(fixture(),flow,c);const r=z.rows.find(r=>r.category==='Necessidade saúde nova');assert.equal(r.months[0].target,100);assert.equal(r.months[0].strategy.floor,100);assert.equal(r.months[0].strategy.needsReview,true);assert.match(r.months[0].strategy.reason,/outras necessidades/);assert(z.months.every(x=>x.target!==null));});
